;------------------------------------------------------------------------------; Scripteur ......: Daniel Lafrance, Québec, canada.; Nom du fichier .: l-c64-joystick.asm; Type fichier....: Librairie ; Creation........: 20251208 ; Version.........: 0.1.0; Révisions.......: 20261030-000000 Francisation des commentaires,;------------------------------------------------------------------------------; Ces fonctions nécessite l'inclusion des variables contenue dans:;              .include "v_c64_showregs.asm"; Ces fonction utilise les routines de conversion contenues dans:;              .include "l-cbm-conv.asm";------------------------------------------------------------------------------; On prend une photo de tous les registres et on les place en mémoire.;------------------------------------------------------------------------------rxloc        = 10ryloc        = 8printregs      .macro               ; Macro sans paramètres.               jsr   regsphoto      ; Prend une photo des registres.               #locate 8,6          ; Positionne le curseur pour                #outstr reg_titre    ; ... afficher le titre.               #locate rxloc,ryloc  ; Positionne le curseur pour               jsr   showregs       ; ... afficher les registres.               #locate 11,24   ; Positionne le curseur pour                #outstr contstr      ; ... afficher le message                #brkpoint 'c'        ; ... [c] pour continuer.               .endm                ; Fin de macro.;------------------------------------------------------------------------------; Prend une photo des registres au moment de l'appel de cette fonction.;------------------------------------------------------------------------------regsphoto      .block               php                  ; Sauve le registre P. stack-> p, pch, pcl               sta   vrega          ; Sauve Acc en mémoire.               pla                  ; stack-> pcl, pch               sta   vregsr         ; Sauve P en mémoire.               stx   vregx          ; Sauve X en mémoire.               sty   vregy          ; Sauve Y en mémoire.               tsx                  ; Copie S san X.               stx   vregsp         ; Sauve S en mémoire.               pla                  ; Récupère pcl. stack-> pch                    sta   vregpcl        ; Sauve pcl en mémoire.                pla                  ; Récupère pch. stack->                sta   vregpch        ; Sauve pch en mémoire.               lda   vrega          ; conversion de A en hexadecimal               pha                  ; stack-> a               lda   zpage1         ; Fais une copie du LSB de zpage1               sta   vzp1l          ; ... mémoire.               lda   zpage1+1       ; Fais une copie du MSB de zpage1               sta   vzp1h          ; ... mémoire.               lda   zpage2         ; Fais une copie du LSB de zpage2               sta   vzp2l          ; ... mémoire.               lda   zpage2+1       ; Fais une copie du MSB de zpage2               sta   vzp2h          ; ... mémoire.               lda   vregpch        ; Récupère le MSB du PC et le remet                pha                  ; ... sur la pile. stack-> pch               lda   vregpcl        ; Récupère le LSB du PC et le remet                pha                  ; ... sur la pile. stack-> pcl, pch               ldy   vregy          ; Récupère la valeur de Y.               ldx   vregx          ; Récupère la valeur de X.               lda   vregsr         ; Récupère la valeur du registre de status               pha                  ; ... remet sur stack-> p, pcl, pch               lda   vrega          ; Récupère la valeur de l'Acc.               plp                  ; Récupère le status. stack-> pcl, pch               rts                  ; L'adresse de retour est sur la pile.               .bend;------------------------------------------------------------------------------; Affiche la valeur des registres au moment de la dernière prise de photo.;------------------------------------------------------------------------------showregs       .block               jsr   push           ; Sauvegarde les registres.               #outcar  b_blanc     ; On s'assure que le texte sera en blanc.               ;---------------------------------------------------------------               ; L'adresse de retour placé sur la pile par JSR affiche un                ; ... retard d'un octet par rapport à l'adresse réelle de                ; ... l'instruction suivante.               ; Il est donc nécessaire de l'augmenter de un octet pour                ; ... obtenir l'adresse réelle de l'instruction suivante.                ;---------------------------------------------------------------               clc                  ; Carry à 0 pour.               inc   vregpcl        ; Incrémente le LSB de l'adresse de retour.               bcc   norep          ; Si Carry à 0 pas de report.               inc   vregpch        ; Report à faire sur le MSB.               ;--------------------                  ; Accumulateur (A)               ;--------------------   norep          #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               lda   vrega          ; Charge la valeur du registre Acc.               #outstr ra_str       ; Affiche le texte explicatif.               jsr   putahexfmt     ; Affiche la valeur en hexadécimal.               ;--------------------                  ; Registre X               ;--------------------                  #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               lda   vregx          ; Charge la valeur du registre x.               #outstr rx_str       ; Affiche le texte explicatif.               jsr   putahexfmt     ; Affiche la valeur en hexadécimal.               ;--------------------                  ; Registre Y               ;--------------------                  #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               lda   vregy          ; Charge la valeur du registre y.               #outstr ry_str       ; Affiche le texte explicatif.               jsr   putahexfmt     ; Affiche la valeur en hexadécimal.               ;--------------------                  ; Status Register               ;--------------------                  #ligneplus  rxloc+9  ; Descend d'une ligne et alligne le debut.               lda   vregsr         ; Charge la valeur du registre sr.               #outstr srh_str      ; Affiche le texte explicatif.               #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               #outstr sr_str       ; Affiche le texte explicatif.               jsr   putabinfmt     ; Affiche la valeur en hexadécimal.               ;--------------------                  ; Stack Pointer               ;--------------------                  #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               lda   vregsp         ; Charge la valeur du registre sp.               #outstr sp_str       ; Affiche le texte explicatif.               jsr   putahexfmt     ; Affiche la valeur en hexadécimal.               ;--------------------                  ; Program Counter               ;--------------------                  #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               ldy   vregpch        ; Charge la valeur MSB du registre pc.               ldx   vregpcl        ; Charge la valeur LSB du registre pc.               jsr   yxtohex        ; Converti YYXX en hexadécimal 16 bits.               #outstr pc_str       ; Affiche le texte explicatif.               #outstr  a2hexpfx    ; Affiche la valeur en hexadécimal 16 bits.               ;--------------------                  ; Zero Page 1               ;--------------------                  #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               ldy   vzp1h          ; Charge la valeur MSB se zpage1.               ldx   vzp1l          ; Charge la valeur LSB se zpage1.               jsr   yxtohex        ; Converti YYXX en hexadécimal 16 bits.                #outstr z1_str       ; Affiche le texte explicatif.               #outstr  a2hexpfx    ; Affiche la valeur en hexadécimal 16 bits.               ;--------------------                  ; Zero Page 2               ;--------------------                  #ligneplus  rxloc    ; Descend d'une ligne et alligne le debut.               ldy   vzp2h          ; Charge la valeur MSB se zpage2.               ldx   vzp2l          ; Charge la valeur LSB se zpage3.               jsr   yxtohex        ; Converti YYXX en hexadécimal 16 bits.               #outstr z2_str       ; Affiche le texte explicatif.               #outstr  a2hexpfx    ; Affiche la valeur en hexadécimal 16 bits.               jsr   pop            ; Récupère les registres.               rts               .bend;------------------------------------------------------------------------------; Déplace le curseur une ligne plus bas, mais sur la même colonne de départ.;------------------------------------------------------------------------------ligneplus     .macro coln               jsr   push           ; Sauvegarde les registres.                             sec                  ; Carry = 1, plot = get               jsr   plot           ; Récupère la position du curseur.               inx                  ; Avance la ligne de 1.               ldy   #\coln         ; Charge la ligne donnée en paramètre.               clc                  ; Carry = 0, plot = set               jsr   plot           ; POsitionne le curseur.               jsr   pop            ; Récupère les registres.               .endm